# Check if the log file exists and read its content
def check_log_file():
    try:
        with open("logs.txt", "r") as f:
            content = f.read()
            assert content != "", "Log file is empty."
            print(content)
    except FileNotFoundError:
        print("Log file does not exist.")
    except AssertionError as e:
        print(e)

check_log_file()
